import functools
from typing import Any, Callable, Protocol

from evaluation.config import GLOBAL_CONFIG
from evaluation.graph_structure import Graph
from evaluation.input import input_td_to_ntd, read_inputs
from evaluation.shim import DPState, extract_solution, forget_callback, introduce_callback, join_callback, leaf_callback
from evaluation.tree_decomposition import FORGET, INTRODUCE, JOIN, LEAF, NiceTreeDecomposition

# Autogenerated.


class DPFunc(Protocol):
    def __call__(
        self,
        ntd: NiceTreeDecomposition,
        input_graph: Graph,
        **kwargs,
    ) -> int: ...


class NoDeleteDict(dict):
    """
    @brief A dictionary subclass that prevents the actual deletion of its items.

    Only deletion-related methods are overridden (__delitem__, pop, popitem, clear).
    All other dictionary methods (e.g., __getitem__, __setitem__, __len__,
    keys(), values(), items(), get(), update(), setdefault()) are inherited
    directly from the built-in `dict` class and behave identically.
    """

    def __init__(self, *args, **kwargs):
        """
        @brief Initializes the NoDeleteDict.
               This constructor behaves exactly like the built-in dict's
               __init__ method, allowing you to initialize it from other
               mappings, keyword arguments, etc.
        """
        super().__init__(*args, **kwargs)

    def __delitem__(self, key):
        """
        @brief Overrides the `del d[key]` operation. This method does nothing,
               effectively preventing the item from being deleted.
        """
        pass  # Do nothing, item remains in the dictionary

    def pop(self, key, *args):
        """
        @brief Overrides the `d.pop(key[, default])` method. It returns the
               value associated with the key, but does NOT remove the item.
        @param key The key whose value is to be returned.
        @param *args: An optional single argument which is the default value
                      to return if the key is not found.
        @return The value associated with 'key', or 'default' if provided and
                the key is not found.
        """
        if key not in self:  # Use dict's standard __contains__ behavior
            if args:  # A default value was provided
                return args[0]
            else:
                raise KeyError(key)

        # If the key exists, return its value without deleting it.
        return self[key]  # Use dict's standard __getitem__ behavior

    def popitem(self):
        """
        @brief Overrides the `d.popitem()` method. It returns an arbitrary
               (key, value) pair, but does NOT remove it from the dictionary.
        @return A (key, value) tuple from the dictionary.
        """
        if not self:  # Use dict's standard __len__ behavior (empty check)
            raise KeyError("popitem(): dictionary is empty")

        # Get an arbitrary item without actually removing it from the dictionary.
        key, value = next(iter(self.items()))  # Uses dict's standard items() and iterator
        return (key, value)

    def clear(self):
        """
        @brief Overrides the `d.clear()` method. This method does nothing,
               effectively preventing all items from being cleared.
        """
        pass  # Do nothing, all items remain in the dictionary


def dp_solution(
    ntd: NiceTreeDecomposition,
    input_graph: Graph,
    **kwargs,
) -> int:

    # Initialise the table. Prevent hacking.
    dp: list[dict[DPState, int]] = [NoDeleteDict() for _ in range(ntd.num_bags)]

    def dp_callback(
        cur_bag_info: tuple[int, set[int]],
        children_info: list[tuple[int, set[int]]],
    ):
        bag_id, bag = cur_bag_info
        bag_type_id, affected_vertex = ntd.b2type[bag_id]

        if bag_type_id == LEAF:
            leaf_vertex = next(iter(bag))
            leaf_callback(
                graph=input_graph.induced_subgraph([leaf_vertex]),
                cur_table=dp[bag_id],
                cur_bag_info=cur_bag_info,
                leaf_vertex=leaf_vertex,
            )
        elif bag_type_id == INTRODUCE:
            assert (
                len(children_info) == 1
            ), f"Introduce node should have 1 child, but got {len(children_info)}: {children_info}"
            child_bag_i, _ = children_info[0]
            introduce_callback(
                graph=input_graph.induced_subgraph(list(bag)),
                cur_table=dp[bag_id],
                cur_bag_info=cur_bag_info,
                child_table=dp[child_bag_i],
                child_bag_info=children_info[0],
                introduced_vertex=affected_vertex,
            )
        elif bag_type_id == FORGET:
            assert (
                len(children_info) == 1
            ), f"Forget node should have 1 child, but got {len(children_info)}: {children_info}"
            child_bag_i, _ = children_info[0]
            forget_callback(
                graph=input_graph.induced_subgraph(list(bag) + [affected_vertex]),
                cur_table=dp[bag_id],
                cur_bag_info=cur_bag_info,
                child_table=dp[child_bag_i],
                child_bag_info=children_info[0],
                forgotten_vertex=affected_vertex,
            )
        elif bag_type_id == JOIN:
            assert (
                len(children_info) == 2
            ), f"Join node should have 2 children, but got {len(children_info)}: {children_info}"
            assert children_info[0][1] == children_info[1][1], "in a join node, child bags must be the same"
            left_child_bag_i, _ = children_info[0]
            right_child_bag_i, _ = children_info[1]
            join_callback(
                graph=input_graph.induced_subgraph(list(bag)),
                cur_table=dp[bag_id],
                cur_bag_info=cur_bag_info,
                left_child_table=dp[left_child_bag_i],
                left_child_bag_info=children_info[0],
                right_child_table=dp[right_child_bag_i],
                right_child_bag_info=children_info[1],
            )

    ntd.traverse(dp_callback)

    result = extract_solution(dp[0])  # Extract the value from the root's table.
    return result


def solve_dp_task(
    graph: tuple[int, int, list[tuple[int, int]]],
    vertex_weights: list[int] | None,
    edge_weights: list[int] | None,
    ntd_func: Callable[[tuple[int, int, list[tuple[int, int]]]], NiceTreeDecomposition],
    dp_func: DPFunc,
    ntd_func_kwargs: dict[str, Any] | None = None,
    dp_func_kwargs: dict[str, Any] | None = None,
) -> int:

    n, m, edge_list = graph
    if ntd_func_kwargs is None:
        ntd_func_kwargs = {}
    ntd = ntd_func(graph, **ntd_func_kwargs)
    if dp_func_kwargs is None:
        dp_func_kwargs = {}
    result = dp_func(
        ntd,
        Graph(
            n=n,
            m=m,
            edges=edge_list,
            vertex_weights=(dict(enumerate(vertex_weights)) if vertex_weights is not None else None),
            edge_weights=edge_weights,
        ),
        **dp_func_kwargs,
    )

    return result


def solve(varz: dict[str, Any], is_vertex_formula: bool) -> int:

    ntd_func = input_td_to_ntd
    ntd_func = functools.partial(
        ntd_func,
        tree_decomposition=varz["tree_decomposition"],
    )

    return solve_dp_task(
        graph=varz["graph"],
        vertex_weights=varz["x_s"] if is_vertex_formula else None,
        edge_weights=varz["x_s"] if (not is_vertex_formula) else None,
        ntd_func=ntd_func,
        dp_func=dp_solution,
        ntd_func_kwargs={},
        dp_func_kwargs={},
    )


def main():
    input_map = read_inputs()
    answer = solve(
        input_map,
        is_vertex_formula=GLOBAL_CONFIG["IS_VERTEX_SET_FORMULA"],
    )
    print(str(answer))


if __name__ == "__main__":
    main()
